def get_flat_questions(position_key):
    pos = QUESTIONS[position_key]
    flat = []
    for competency, questions in pos["competencies"].items():
        for q in questions:
            flat.append({"competency": competency, "question": q})
    return flat


def get_cases(position_key):
    return CASES.get(position_key, [])


def get_reference_answer(position_key, question):
    """Возвращает эталонный ответ для данного вопроса"""
    refs = QUESTIONS[position_key].get("reference_answers", {})
    return refs.get(question, "")
